import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { TfiClose } from "react-icons/tfi";
import { IoMdClose } from "react-icons/io"; // Extra icon for deleting items

const SearchOverlay = ({ isSearchOpen, setIsSearchOpen }) => {
  const [query, setQuery] = useState("");
  const [history, setHistory] = useState([]);
  const HISTORY_LIMIT = 5;

  // 1. Load history from localStorage on mount
  useEffect(() => {
    const savedHistory = localStorage.getItem("searchHistory");
    if (savedHistory) {
      setHistory(JSON.parse(savedHistory));
    }
  }, []);

  // 2. Function to save a new search
  const handleSearch = (e) => {
    if (e.key === "Enter" && query.trim() !== "") {
      const newHistory = [
        query,
        ...history.filter((item) => item !== query), // Remove duplicates
      ].slice(0, HISTORY_LIMIT); // Keep only the latest 5

      setHistory(newHistory);
      localStorage.setItem("searchHistory", JSON.stringify(newHistory));

      // Optional: Logic to actually perform the search goes here
      console.log("Searching for:", query);
      setQuery(""); // Clear input after search
    }
  };

  // 3. Function to remove a specific item
  const removeHistoryItem = (itemToDelete) => {
    const updatedHistory = history.filter((item) => item !== itemToDelete);
    setHistory(updatedHistory);
    localStorage.setItem("searchHistory", JSON.stringify(updatedHistory));
  };

  return (
    <AnimatePresence>
      {isSearchOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[60] bg-background/95 backdrop-blur-xl flex flex-col pt-32 px-6"
        >
          {/* Close Button */}
          <button
            onClick={() => setIsSearchOpen(false)}
            className="absolute top-8 right-8 p-3 hover:bg-white/10 rounded-full transition-colors"
          >
            <TfiClose className="text-2xl text-foreground" />
          </button>

          <div className="w-full max-w-4xl mx-auto">
            <span className="text-[10px] font-black text-foreground-subtle uppercase tracking-widest mb-4 block">
              Search Collection
            </span>

            {/* Search Input */}
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleSearch}
              placeholder="Start typing..."
              className="w-full text-4xl md:text-7xl font-black uppercase tracking-tighter border-b-4 border-border focus:border-brand bg-transparent py-4 outline-none transition-colors placeholder:text-foreground-subtle/20"
              autoFocus
            />

            {/* History List */}
            {history.length > 0 && (
              <div className="mt-8">
                <h4 className="text-[10px] font-bold uppercase tracking-widest text-foreground-subtle mb-4">
                  Recent Searches
                </h4>
                <div className="flex flex-col gap-2">
                  {history.map((item, index) => (
                    <div
                      key={index}
                      className="group flex items-center justify-between py-2 border-b border-white/5 hover:border-brand transition-colors"
                    >
                      <button
                        onClick={() => setQuery(item)}
                        className="text-xl md:text-2xl font-medium text-foreground/60 hover:text-foreground transition-colors"
                      >
                        {item}
                      </button>
                      <button
                        onClick={() => removeHistoryItem(item)}
                        className="p-2 opacity-0 group-hover:opacity-100 hover:text-red-500 transition-all"
                      >
                        <IoMdClose />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default SearchOverlay;
